class Solution {
    private int[] parent;
    private int[] rank;
    private int[] size;

    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        parent = new int[n];
        rank = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (graph[i][j] == 1) {
                    union(i, j);
                }
            }
        }

        java.util.Map<Integer, Integer> compInfected = new java.util.HashMap<>();
        for (int node : initial) {
            int root = find(node);
            compInfected.merge(root, 1, Integer::sum);
        }

        java.util.Arrays.sort(initial);
        int bestNode = initial[0];
        int bestSave = 0;
        for (int node : initial) {
            int root = find(node);
            if (compInfected.get(root) == 1 && size[root] > bestSave) {
                bestSave = size[root];
                bestNode = node;
            }
        }
        return bestNode;
    }

    private int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    private void union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) {
            return;
        }
        if (rank[ra] < rank[rb]) {
            int temp = ra;
            ra = rb;
            rb = temp;
        }
        parent[rb] = ra;
        size[ra] += size[rb];
        if (rank[ra] == rank[rb]) {
            rank[ra]++;
        }
    }
}

