class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        int[] componentId = new int[n];
        Arrays.fill(componentId, -1);
        List<Integer> compSize = new ArrayList<>();
        int label = 0;
        for (int i = 0; i < n; i++) {
            if (componentId[i] == -1) {
                compSize.add(dfs(graph, i, componentId, label));
                label++;
            }
        }

        Map<Integer, Integer> compInfectedCount = new HashMap<>();
        for (int node : initial) {
            int comp = componentId[node];
            compInfectedCount.merge(comp, 1, Integer::sum);
        }

        Arrays.sort(initial);
        int bestNode = initial[0];
        int bestSave = 0;
        for (int node : initial) {
            int comp = componentId[node];
            if (compInfectedCount.get(comp) == 1) {
                int save = compSize.get(comp);
                if (save > bestSave) {
                    bestSave = save;
                    bestNode = node;
                }
            }
        }
        return bestNode;
    }

    private int dfs(int[][] graph, int node, int[] componentId, int label) {
        componentId[node] = label;
        int size = 1;
        for (int next = 0; next < graph.length; next++) {
            if (graph[node][next] == 1 && componentId[next] == -1) {
                size += dfs(graph, next, componentId, label);
            }
        }
        return size;
    }
}

