class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        Arrays.sort(initial);
        int n = graph.length;
        int bestNode = initial[0];
        int bestCount = Integer.MAX_VALUE;
        for (int removed : initial) {
            boolean[] infected = new boolean[n];
            Queue<Integer> queue = new ArrayDeque<>();
            for (int node : initial) {
                if (node != removed && !infected[node]) {
                    infected[node] = true;
                    queue.offer(node);
                }
            }
            while (!queue.isEmpty()) {
                int node = queue.poll();
                for (int next = 0; next < n; next++) {
                    if (graph[node][next] == 1 && !infected[next]) {
                        infected[next] = true;
                        queue.offer(next);
                    }
                }
            }
            int count = 0;
            for (boolean value : infected) {
                if (value) {
                    count++;
                }
            }
            if (count < bestCount) {
                bestCount = count;
                bestNode = removed;
            }
        }
        return bestNode;
    }
}

