class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[] initiallyInfected = new boolean[n];
        for (int node : initial) {
            initiallyInfected[node] = true;
        }

        int[] savedByNode = new int[n];
        boolean[] visited = new boolean[n];
        for (int start = 0; start < n; start++) {
            if (visited[start]) {
                continue;
            }
            ArrayDeque<Integer> queue = new ArrayDeque<>();
            List<Integer> component = new ArrayList<>();
            queue.offer(start);
            visited[start] = true;
            int owner = -1;
            boolean multipleOwners = false;

            while (!queue.isEmpty()) {
                int node = queue.poll();
                component.add(node);
                if (initiallyInfected[node]) {
                    if (owner == -1) {
                        owner = node;
                    } else {
                        multipleOwners = true;
                    }
                }
                for (int next = 0; next < n; next++) {
                    if (graph[node][next] == 1 && !visited[next]) {
                        visited[next] = true;
                        queue.offer(next);
                    }
                }
            }

            if (owner != -1 && !multipleOwners) {
                savedByNode[owner] += component.size();
            }
        }

        Arrays.sort(initial);
        int bestNode = initial[0];
        for (int node : initial) {
            if (savedByNode[node] > savedByNode[bestNode]) {
                bestNode = node;
            }
        }
        return bestNode;
    }
}

