class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        boolean[][] reach = new boolean[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                reach[i][j] = graph[i][j] == 1;
            }
        }

        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                if (!reach[i][k]) {
                    continue;
                }
                for (int j = 0; j < n; j++) {
                    reach[i][j] = reach[i][j] || reach[k][j];
                }
            }
        }

        Arrays.sort(initial);
        int bestNode = initial[0];
        int bestInfected = Integer.MAX_VALUE;
        for (int removed : initial) {
            int infectedCount = 0;
            for (int node = 0; node < n; node++) {
                boolean infected = false;
                for (int source : initial) {
                    if (source != removed && reach[source][node]) {
                        infected = true;
                        break;
                    }
                }
                if (infected) {
                    infectedCount++;
                }
            }
            if (infectedCount < bestInfected) {
                bestInfected = infectedCount;
                bestNode = removed;
            }
        }
        return bestNode;
    }
}
